38	/**
39	 * Mostly used as a facade for all Petclinic controllers
40	 * Also a placeholder for @Transactional and @Cacheable annotations
41	 *
42	 * @author Michael Isvy
43	 * @author Vitaliy Fedoriv
44	 */
45	@Service
46	public class ClinicServiceImpl implements ClinicService {
47	
48	    /**
49	     * Dedicated audit logger. Successful owner creates emit a single line here carrying the new
50	     * owner's id, customer code and registration date.
51	     */
52	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
53	
54	    /**
55	     * Maximum number of owners allowed in a single city. Creating an owner in a city that already
56	     * contains this many owners is rejected with {@link CityAtCapacityException}.
57	     */
58	    static final int MAX_OWNERS_PER_CITY = 50;
59	
60	    /**
61	     * Maximum number of owners that may be registered on a single day. Creating an owner on a day
62	     * that already has this many owners (counted by {@code registrationDate}) is rejected with
63	     * {@link DailyRegistrationLimitException}.
64	     */
65	    static final int MAX_OWNERS_PER_DAY = 100;
66	
67	    /**
68	     * Threshold of owners registered on a single day (counted by {@code registrationDate}) above
69	     * which a newly created owner is flagged with {@code bulkSignupWarning}. When more than this
70	     * many owners have already been created on that day, the new owner's warning is {@code true}.
71	     */
72	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
73	
74	    private final PetRepository petRepository;
75	    private final VetRepository vetRepository;
76	    private final OwnerRepository ownerRepository;
77	    private final VisitRepository visitRepository;
78	    private final SpecialtyRepository specialtyRepository;
79	    private final PetTypeRepository petTypeRepository;
80	
81	    public ClinicServiceImpl(
82	        PetRepository petRepository,
83	        VetRepository vetRepository,
84	        OwnerRepository ownerRepository,
85	        VisitRepository visitRepository,
86	        SpecialtyRepository specialtyRepository,
87	        PetTypeRepository petTypeRepository) {
88	        this.petRepository = petRepository;
89	        this.vetRepository = vetRepository;
90	        this.ownerRepository = ownerRepository;
91	        this.visitRepository = visitRepository;
92	        this.specialtyRepository = specialtyRepository;
93	        this.petTypeRepository = petTypeRepository;
94	    }
