262	
263	    @Override
264	    @Transactional
265	    public void saveOwner(Owner owner) throws DataAccessException {
266	        saveOwner(owner, false);
267	    }
268	
269	    /**
270	     * Save an owner, enforcing the create-time business rules.
271	     *
272	     * <p>Because the household is keyed on {@code (lastName, postcode)} (see
273	     * {@link Owner#householdId(String, String)}), owners sharing a last name and postcode are the
274	     * same household. On create, a second owner in an existing household is rejected as a household
275	     * duplicate (see {@link #assertHouseholdIsUnique(Owner)}) <em>unless</em> {@code sharesHousehold}
276	     * is set, in which case it is accepted as a declared household member. The {@code sharesHousehold}
277	     * flag therefore only bypasses that duplicate block; a declared member is also not flagged as a
278	     * possible (suspected) duplicate.
279	     */
280	    @Override
281	    @Transactional
282	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
283	        boolean isCreate = owner.isNew();
284	        assertEmailDomainAllowed(owner);
285	        assertIdentityIsUnique(owner);
286	        if (owner.isNew()) {
287	            assertCityHasCapacity(owner);
288	            if (!sharesHousehold) {
289	                assertHouseholdIsUnique(owner);
290	            }
291	        }
292	        if (owner.getRegistrationDate() == null) {
293	            owner.setRegistrationDate(LocalDate.now());
294	        }
295	        assertRegistrationDateNotInFuture(owner);
296	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
297	        if (owner.isNew()) {
298	            assertDailyRegistrationLimit(owner);
299	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
300	        }
301	        if (owner.isNew() && owner.getCustomerCode() == null) {
302	            owner.setCustomerCode(generateCustomerCode(owner));
303	        }
304	        if (owner.isNew() && owner.getNamesakeCount() == null) {
305	            owner.setNamesakeCount(countNamesakes(owner));
306	        }
307	        if (owner.isNew() && owner.getHouseholdCount() == null) {
308	            owner.setHouseholdCount(countHouseholdMembers(owner));
309	        }
310	        if (owner.isNew()) {
311	            assignPossibleDuplicate(owner, sharesHousehold);
312	        }
313	        ownerRepository.save(owner);
314	        if (isCreate) {
315	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
316	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
317	        }
318	    }
319	
320	    /**
321	     * Count the existing owners that, at the moment this owner is created, share its first name
322	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
323	     * it never counts itself. This value is deterministic given the current data, so it is computed
324	     * once at creation time and stored.
325	     */
326	    private Integer countNamesakes(Owner owner) {
327	        String firstName = owner.getFirstName();
328	        String lastName = owner.getLastName();
329	        if (firstName == null || lastName == null) {
330	            return 0;
331	        }
332	        return (int) ownerRepository.findAll().stream()
333	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
334	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
335	                && lastName.equalsIgnoreCase(existing.getLastName()))
336	            .count();
337	    }
338	
339	    /**
340	     * Count the members of this owner's household at the moment it is created, i.e. the number of
341	     * owners sharing its household id (same last name and postcode, see
342	     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
343	     * household id (missing last name or postcode) is counted as a single-member household. The value
344	     * is deterministic given the current data, so it is computed once at creation time and stored.
345	     */
346	    private Integer countHouseholdMembers(Owner owner) {
347	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
348	        if (householdId == null) {
349	            return 1;
350	        }
351	        long others = ownerRepository.findAll().stream()
352	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
353	            .filter(existing -> householdId.equals(
354	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
355	            .count();
356	        return (int) others + 1;
357	    }
358	
359	    /**
360	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
361	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
362	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
363	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
364	     * value is deterministic in those fields and carries no sequence number (see
365	     * {@link Owner#customerCode(String, String, String)}).
366	     */
367	    private String generateCustomerCode(Owner owner) {
368	        return Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
369	    }
370	
371	    /**
372	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
373	     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
374	     * {@link #assertIdentityIsUnique(Owner)}, and an undeclared household duplicate by
375	     * {@link #assertHouseholdIsUnique(Owner)}, before this runs. This detects the weaker overlap: an
376	     * existing owner that shares this owner's household id (same last name and postcode, see
377	     * {@link Owner#householdId(String, String)}) but has a <em>different</em> normalized telephone.
378	     * When such an owner exists, {@code possibleDuplicate} is set {@code true} and
379	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
380	     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
381	     *
382	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
383	     * deliberately joins an existing household, so it is left unflagged.
384	     */
385	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
386	        if (sharesHousehold) {
387	            owner.setPossibleDuplicate(false);
388	            owner.setPossibleDuplicateOf(null);
389	            return;
390	        }
391	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
392	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
393	        Integer match = null;
394	        if (householdId != null) {
395	            match = ownerRepository.findAll().stream()
396	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
397	                .filter(existing -> householdId.equals(
398	                    Owner.householdId(existing.getLastName(), existing.getPostcode())))
399	                .filter(existing -> !Objects.equals(normalizedTelephone,
400	                    Owner.normalizeTelephone(existing.getTelephone())))
401	                .map(Owner::getId)
402	                .filter(Objects::nonNull)
403	                .min(Integer::compareTo)
404	                .orElse(null);
405	        }
406	        owner.setPossibleDuplicate(match != null);
407	        owner.setPossibleDuplicateOf(match);
408	    }
409	
410	    /**
411	     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
412	     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
413	     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
414	     * constraint.
415	     */
416	    private void assertEmailDomainAllowed(Owner owner) {
417	        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
418	            throw new DisposableEmailDomainException(owner.getEmail());
419	        }
420	    }
421	
422	    /**
423	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
424	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
425	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
426	     * (normalized telephone, normalized email (or empty) and household id, see
427	     * {@link Owner#identityKey(String, String, String, String)}).
428	     *
429	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
430	     * key when their normalized telephones already match; the normalized telephone is therefore the
431	     * decisive component and is what this check compares. Consequently two members of the same
432	     * household with different telephones have different identity keys and are both allowed, while
433	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
434	     * excluded by id so updating an owner in place never conflicts with itself.
435	     */
436	    private void assertIdentityIsUnique(Owner owner) {
437	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
438	        if (normalizedTelephone == null) {
439	            return;
440	        }
441	        boolean duplicate = ownerRepository.findAll().stream()
442	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
443	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
444	            .anyMatch(normalizedTelephone::equals);
445	        if (duplicate) {
446	            throw new DuplicateIdentityException(Owner.identityKey(
447	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
448	        }
449	    }
450	
451	    /**
452	     * Enforce that no <em>other</em> owner already belongs to this owner's household, throwing
453	     * {@link DuplicateIdentityException} if one does. The household is keyed on {@code (lastName,
454	     * postcode)} (see {@link Owner#householdId(String, String)}), so owners sharing a last name and
455	     * postcode are the same household and a second such owner is a household duplicate. The owner
456	     * being saved is excluded by id, and an owner with no derivable household id (missing last name
457	     * or postcode) places no constraint. Callers bypass this check for a declared household member
458	     * ({@code sharesHousehold} set).
459	     */
460	    private void assertHouseholdIsUnique(Owner owner) {
461	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
462	        if (householdId == null) {
463	            return;
464	        }
465	        boolean duplicate = ownerRepository.findAll().stream()
466	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
467	            .map(existing -> Owner.householdId(existing.getLastName(), existing.getPostcode()))
468	            .anyMatch(householdId::equals);
469	        if (duplicate) {
470	            throw new DuplicateIdentityException(Owner.identityKey(
471	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
472	        }
473	    }
474	
475	    /**
476	     * Enforce that the owner's city has not yet reached its capacity, throwing
477	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
478	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
479	     */
480	    private void assertCityHasCapacity(Owner owner) {
481	        String city = owner.getCity();
482	        if (city == null) {
483	            return;
484	        }
485	        long count = ownerRepository.findAll().stream()
486	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
487	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
488	            .count();
489	        if (count >= MAX_OWNERS_PER_CITY) {
490	            throw new CityAtCapacityException(city);
491	        }
492	    }
493	
494	    /**
495	     * Enforce that the owner's registration date is not later than the current server date, throwing
496	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
497	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
498	     * harmless no-op for that case.
499	     */
500	    private void assertRegistrationDateNotInFuture(Owner owner) {
501	        LocalDate registrationDate = owner.getRegistrationDate();
502	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
503	            throw new FutureRegistrationDateException(registrationDate);
504	        }
505	    }
506	
507	    /**
508	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
509	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
510	     * the effective registration date (whether supplied in the request or defaulted to the server
511	     * date) so that every value derived from it&mdash;such as the membership number's year segment
512	     * and the daily create-limit counting&mdash;uses the adjusted business day.
513	     */
514	    private static LocalDate rollToBusinessDay(LocalDate date) {
515	        if (date == null) {
516	            return null;
517	        }
518	        DayOfWeek dayOfWeek = date.getDayOfWeek();
519	        if (dayOfWeek == DayOfWeek.SATURDAY) {
520	            return date.plusDays(2);
521	        }
522	        if (dayOfWeek == DayOfWeek.SUNDAY) {
523	            return date.plusDays(1);
524	        }
525	        return date;
526	    }
527	
528	    /**
529	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
530	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
531	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
532	     * is excluded by id.
533	     */
534	    private void assertDailyRegistrationLimit(Owner owner) {
535	        LocalDate registrationDate = owner.getRegistrationDate();
536	        if (registrationDate == null) {
537	            return;
538	        }
539	        long count = ownerRepository.findAll().stream()
540	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
541	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
542	            .count();
543	        if (count >= MAX_OWNERS_PER_DAY) {
544	            throw new DailyRegistrationLimitException(registrationDate);
545	        }
546	    }
547	
548	    /**
549	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
550	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
551	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
552	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
553	     * stored on the owner.
554	     */
555	    private boolean computeBulkSignupWarning(Owner owner) {
556	        LocalDate registrationDate = owner.getRegistrationDate();
557	        if (registrationDate == null) {
558	            return false;
559	        }
560	        long count = ownerRepository.findAll().stream()
561	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
562	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
563	            .count();
564	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
565	    }
566	
567	    @Override
568	    @Transactional(readOnly = true)
569	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
570	        return ownerRepository.findByLastName(lastName);
571	    }
572	
573	    @Override
574	    @Transactional(readOnly = true)
575	    public Collection<Visit> findVisitsByPetId(int petId) {
576	        return visitRepository.findByPetId(petId);
577	    }
578	
579	    @Override
580	    @Transactional(readOnly = true)
581	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
582	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
583	    }
584	
585	    private <T> T findEntityById(Supplier<T> supplier) {
586	        try {
587	            return supplier.get();
588	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
589	            // Just ignore not found exceptions for Jdbc/Jpa realization
590	            return null;
591	        }
592	    }
593	
594	}
